func (db *database) migrateV20ToV21() error {
	_, err := db.conn.Exec(`ALTER TABLE settings ADD COLUMN gama_modules INTEGER NOT NULL DEFAULT 1`)
	if err != nil && !duplicateColumnError(err) {
		return fmt.Errorf("add gama_modules: %w", err)
	}
	// Match the fresh-install schema before advancing the version.
	if _, err := db.conn.Exec(`CREATE TABLE IF NOT EXISTS gama_favorites (chat_id TEXT PRIMARY KEY REFERENCES chats(id) ON DELETE CASCADE)`); err != nil {
		return fmt.Errorf("create gama_favorites: %w", err)
	}
	if _, err := db.conn.Exec(`CREATE TABLE IF NOT EXISTS gama_skills (name TEXT PRIMARY KEY, description TEXT NOT NULL, instructions TEXT NOT NULL)`); err != nil {
		return fmt.Errorf("create gama_skills: %w", err)
	}
	_, err = db.conn.Exec(`UPDATE settings SET schema_version = 21`)
	return err
}

