package ui

import (
 "fmt"
 "math"
 "strings"
 "unicode/utf8"

 "github.com/ollama/ollama/api"
)

type gamaInference struct {
 Model string `json:"model"`
 Temperature *float64 `json:"temperature,omitempty"`
 TopP *float64 `json:"top_p,omitempty"`
 NumPredict *int `json:"num_predict,omitempty"`
 System string `json:"system,omitempty"`
}

func (g *gamaInference) validate(model string) error {
 if g.Model != model || strings.TrimSpace(model)=="" { return fmt.Errorf("Gama model mismatch") }
 valid := func(v *float64, low, high float64) bool { return v==nil || (!math.IsNaN(*v) && !math.IsInf(*v,0) && *v>=low && *v<=high) }
 if !valid(g.Temperature,0,1.5) || !valid(g.TopP,0.05,1) { return fmt.Errorf("Gama sampling parameter out of bounds") }
 if g.NumPredict!=nil && (*g.NumPredict<64 || *g.NumPredict>4096) { return fmt.Errorf("Gama output limit out of bounds") }
 if utf8.RuneCountInString(g.System)>1200 { return fmt.Errorf("Gama system prompt too long") }
 return nil
}

func (g *gamaInference) apply(req *api.ChatRequest) {
 if req.Options==nil { req.Options=make(map[string]any) }
 if g.Temperature!=nil { req.Options["temperature"]=*g.Temperature }
 if g.TopP!=nil { req.Options["top_p"]=*g.TopP }
 if g.NumPredict!=nil { req.Options["num_predict"]=*g.NumPredict }
 if text:=strings.TrimSpace(g.System); text!="" {
   req.Messages=append([]api.Message{{Role:"system", Content:text}},req.Messages...)
 }
}

