package ui

import (
 "encoding/json"
 "fmt"
 "net/http"
 "regexp"
 "strings"
 "unicode/utf8"

 "github.com/ollama/ollama/app/store"
)

var gamaSkillName=regexp.MustCompile("^[a-z0-9]+(-[a-z0-9]+)*$")

// Restricted text-only subset of SKILL.md. Metadata is never interpreted as permissions.
func parseGamaSkill(raw string)(store.GamaSkill,error){
 var x store.GamaSkill
 if len(raw)>32768 || !utf8.ValidString(raw){return x,fmt.Errorf("invalid skill size or encoding")}
 raw=strings.ReplaceAll(strings.TrimPrefix(raw,"\uFEFF"),"\r\n","\n")
 if !strings.HasPrefix(raw,"---\n"){return x,fmt.Errorf("SKILL.md needs frontmatter")}
 header,body,ok:=strings.Cut(raw[4:],"\n---\n")
 if !ok{return x,fmt.Errorf("missing closing frontmatter")}
 for _,line:=range strings.Split(header,"\n"){
  key,v,ok:=strings.Cut(line,":")
  if !ok{continue}
  v=strings.Trim(strings.TrimSpace(v),"\"'")
  switch strings.TrimSpace(key){
  case "name": if x.Name!=""{return x,fmt.Errorf("duplicate name")};x.Name=v
  case "description": if x.Description!=""{return x,fmt.Errorf("duplicate description")};x.Description=v
  }
 }
 x.Instructions=strings.TrimSpace(body)
 if len(x.Name)>64||!gamaSkillName.MatchString(x.Name)||x.Description==""||utf8.RuneCountInString(x.Description)>1024||x.Instructions==""||utf8.RuneCountInString(x.Instructions)>6000{return x,fmt.Errorf("invalid name, description, or instruction length")}
 return x,nil
}
func (s *Server) gamaSkillAllowed(w http.ResponseWriter) (bool,error){
 settings,err:=s.Store.Settings();if err!=nil{return false,err}
 if settings.GamaModules & store.GamaSkills==0{http.Error(w,"Gama skills disabled",http.StatusForbidden);return false,nil}
 return true,nil
}
func (s *Server) gamaSkills(w http.ResponseWriter,r *http.Request)error{
 ok,err:=s.gamaSkillAllowed(w);if !ok||err!=nil{return err}
 items,err:=s.Store.GamaSkills(r.Context());if err!=nil{return err}
 w.Header().Set("Content-Type","application/json");w.Header().Set("Cache-Control","no-store")
 return json.NewEncoder(w).Encode(items)
}
func (s *Server) gamaImportSkill(w http.ResponseWriter,r *http.Request)error{
 ok,err:=s.gamaSkillAllowed(w);if !ok||err!=nil{return err}
 var req struct{Text string `json:"text"`}
 if err:=json.NewDecoder(http.MaxBytesReader(w,r.Body,200000)).Decode(&req);err!=nil{return err}
 skill,err:=parseGamaSkill(req.Text);if err!=nil{return err}
 if err:=s.Store.GamaAddSkill(r.Context(),skill);err!=nil{return fmt.Errorf("cannot import skill; duplicate name or library full")}
 w.Header().Set("Content-Type","application/json");return json.NewEncoder(w).Encode(skill)
}
func (s *Server) gamaDeleteSkill(w http.ResponseWriter,r *http.Request)error{
 ok,err:=s.gamaSkillAllowed(w);if !ok||err!=nil{return err}
 name:=r.PathValue("name");if !gamaSkillName.MatchString(name)||len(name)>64{return fmt.Errorf("invalid skill name")}
 if err:=s.Store.GamaDeleteSkill(r.Context(),name);err!=nil{return err};w.WriteHeader(http.StatusNoContent);return nil
}

