// Exclusive within the desktop process. External Ollama clients are not covered;
// the residency guard is conservative, not a cross-process inference lock.
var gamaCouncilGate sync.RWMutex

type gamaCouncilRequest struct {
 Question string `json:"question"`
 Models []string `json:"models"`
 Mode string `json:"mode"`
 Chair string `json:"chair,omitempty"`
}
type gamaCouncilAnswer struct{Model,Text string}
func councilClip(s string,n int)string{r:=[]rune(s);if len(r)>n{return string(r[:n])+" [excerto limitado]"};return s}
func councilContext(rows []gamaCouncilAnswer)string{
 var b strings.Builder
 for _,row:=range rows{fmt.Fprintf(&b,"\nModelo %s: %s\n",row.Model,councilClip(row.Text,700))}
 return b.String()
}
func (q gamaCouncilRequest) valid()bool{
 if strings.TrimSpace(q.Question)==""||utf8.RuneCountInString(q.Question)>1800||len(q.Models)<2||len(q.Models)>4||(q.Mode!="independent"&&q.Mode!="roundtable"&&q.Mode!="redteam"){return false}
 seen:=map[string]bool{}
 for _,name:=range q.Models{if name==""||seen[name]{return false};seen[name]=true}
 return q.Chair==""||seen[q.Chair]
}
func (s *Server) councilAllowed(w http.ResponseWriter)(bool,error){
 settings,err:=s.Store.Settings();if err!=nil{return false,err}
 if settings.GamaModules & store.GamaCouncil==0{http.Error(w,"Conselho desativado",http.StatusForbidden);return false,nil}
 host:=envconfig.Host().Hostname()
 if host!="localhost"&&host!="127.0.0.1"&&host!="::1"{http.Error(w,"Conselho exige servidor local",http.StatusForbidden);return false,nil}
 return true,nil
}
func (s *Server) gamaCouncilModels(w http.ResponseWriter,r *http.Request)error{
