import { useContext,useEffect,useRef,useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { useNavigate } from "@tanstack/react-router";
import { API_BASE } from "@/lib/config";
import { GamaContext,GAMA_COUNCIL } from "./GamaModules";

type Event={event:string;chat_id:string;model:string;content:string};
export function CouncilPanel(props:{chatId:string;busy:boolean;onBusy:(v:boolean)=>void}){
 const flags=useContext(GamaContext);
 return (flags&GAMA_COUNCIL)!==0?<CouncilBody {...props}/>:null;
}
function CouncilBody({chatId,busy,onBusy}:{chatId:string;busy:boolean;onBusy:(v:boolean)=>void}){
 const qc=useQueryClient(), navigate=useNavigate();
 const [open,setOpen]=useState(false),[models,setModels]=useState<string[]>([]),[selected,setSelected]=useState<string[]>([]),[mode,setMode]=useState("independent"),[chair,setChair]=useState(""),[question,setQuestion]=useState(""),[running,setRunning]=useState(false),[status,setStatus]=useState(""),[partial,setPartial]=useState("");
 const abort=useRef<AbortController|null>(null);
 useEffect(()=>()=>{abort.current?.abort();onBusy(false);},[onBusy]);
 const load=async()=>{
  try{const res=await fetch(API_BASE+"/api/v1/gama/council/models",{cache:"no-store"});if(!res.ok)throw Error("models");setModels(await res.json());}
  catch{setStatus("Não foi possível listar modelos locais.");}
 };
 const run=async()=>{
  if(running||busy||selected.length<2||!question.trim())return;
  const c=new AbortController();abort.current=c;setRunning(true);onBusy(true);setStatus("Preparando…");setPartial("");
  let actual=chatId;
  try{
   const response=await fetch(API_BASE+"/api/v1/gama/council/"+encodeURIComponent(chatId),{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({question,models:selected,mode,chair}),signal:c.signal});
   if(!response.ok||!response.body)throw Error("Conselho indisponível. Confira se o servidor está ocioso.");
   const reader=response.body.getReader(),decoder=new TextDecoder();let pending="",terminal=false;
   while(true){
    const {value,done}=await reader.read();pending+=decoder.decode(value,{stream:!done});
    const lines=pending.split("\n");pending=lines.pop()??"";
    for(const line of lines){if(!line.trim())continue;const e=JSON.parse(line) as Event;
     actual=e.chat_id||actual;
     if(e.event==="start"){setStatus(e.model+(e.content==="synthesis"?" · síntese":" · respondendo"));setPartial("");}
     if(e.event==="delta")setPartial(old=>old+e.content);
     if(e.event==="saved"){setPartial("");await qc.invalidateQueries({queryKey:["chat",actual]});}
     if(e.event==="done"){terminal=true;setStatus("Conselho concluído.");}
     if(e.event==="error"){terminal=true;setStatus(e.content);}
    }
    if(done){if(!terminal)throw Error("Fluxo interrompido; confira respostas salvas.");break;}
   }
  }catch(e){setStatus(c.signal.aborted?"Cancelado. Respostas concluídas foram preservadas.":e instanceof Error?e.message:"Falha no Conselho.");}
  finally{
   onBusy(false);setRunning(false);setPartial("");void qc.invalidateQueries({queryKey:["chats"]});
   if(actual!=="new"){void qc.invalidateQueries({queryKey:["chat",actual]});if(chatId==="new")void navigate({to:"/c/$chatId",params:{chatId:actual}});}
  }
 };
 return <div className="px-5 pb-2 text-xs text-neutral-500 dark:text-neutral-400" onKeyDown={e=>e.stopPropagation()}>
  <button type="button" aria-expanded={open} disabled={running} onClick={()=>{setOpen(!open);if(!open)void load();}}>Conselho de IAs</button>
  {open&&<div className="mt-2 rounded-lg border border-neutral-200 dark:border-neutral-700 p-3 space-y-2 max-h-72 overflow-auto">
   <p>Uma rodada independente do histórico anterior. Apenas modelos locais; não use outro cliente Ollama durante a execução.</p>
   <div className="flex flex-wrap gap-2">{models.map(m=><label key={m}><input type="checkbox" checked={selected.includes(m)} disabled={running||(!selected.includes(m)&&selected.length>=4)} onChange={e=>{setSelected(old=>e.target.checked?[...old,m]:old.filter(x=>x!==m));if(!e.target.checked&&chair===m)setChair("");}}/> {m}</label>)}</div>
   <p>Ordem: {selected.join(" → ")||"Selecione de 2 a 4 modelos"}</p>
   <label>Modo <select disabled={running} value={mode} onChange={e=>setMode(e.target.value)}><option value="independent">Independente</option><option value="roundtable">Mesa-redonda</option><option value="redteam">Red Team</option></select></label>
   <label className="block">Síntese <select disabled={running} value={chair} onChange={e=>setChair(e.target.value)}><option value="">Nenhuma</option>{selected.map(m=><option key={m}>{m}</option>)}</select></label>
   <textarea aria-label="Pergunta do Conselho" value={question} onChange={e=>setQuestion(e.target.value)} maxLength={1800} rows={3} disabled={running} className="w-full bg-transparent border rounded p-2"/>
   {running?<button type="button" onClick={()=>abort.current?.abort()}>Cancelar rodada</button>:<button type="button" disabled={busy||selected.length<2||!question.trim()} onClick={()=>void run()}>Iniciar Conselho</button>}
   <p role="status">{status}</p>{partial&&<p className="whitespace-pre-wrap">{partial}</p>}
  </div>}
 </div>;
}

