 "time"
 "unicode/utf8"

 "github.com/ollama/ollama/app/store"
)

var gamaSpeechGate sync.Mutex

// Fixed local executable, no shell, no user-controlled arguments or paths.
// Speech runs only while the authenticated request is active.
func (s *Server) gamaSpeak(w http.ResponseWriter,r *http.Request)error{
 settings,err:=s.Store.Settings();if err!=nil{return err}
 if settings.GamaModules&store.GamaMedia==0||runtime.GOOS!="darwin"{http.Error(w,"Leitura em voz alta indisponível",http.StatusForbidden);return nil}
 var req struct{Text string `json:"text"`}
 if err:=json.NewDecoder(http.MaxBytesReader(w,r.Body,65536)).Decode(&req);err!=nil{return err}
 if strings.TrimSpace(req.Text)==""||utf8.RuneCountInString(req.Text)>5000{return fmt.Errorf("invalid speech text")}
 if !gamaSpeechGate.TryLock(){http.Error(w,"Áudio já em reprodução",http.StatusConflict);return nil};defer gamaSpeechGate.Unlock()
 ctx,cancel:=context.WithTimeout(r.Context(),4*time.Minute);defer cancel()
 cmd:=exec.CommandContext(ctx,"/usr/bin/say","-f","-")
 cmd.Stdin=strings.NewReader(req.Text)
 if err:=cmd.Run();err!=nil{return fmt.Errorf("reprodução local interrompida ou indisponível")}
 w.WriteHeader(http.StatusNoContent);return nil
}

