package ui

import (
 "context"
 "encoding/json"
 "fmt"
 "io"
 "net/http"
 "net/url"
 "os/exec"
 "regexp"
 "runtime"
 "strings"
 "time"
 "github.com/ollama/ollama/api"
)

type gamaSource struct {
 ID string `json:"id"`
 Title string `json:"title"`
 URL string `json:"url"`
 Excerpt string `json:"excerpt"`
}

func gamaKey(ctx context.Context,provider string)(string,error){
 if runtime.GOOS!="darwin"{return "",fmt.Errorf("Keychain disponível apenas no macOS")}
 service,account:="GamaSearch.Brave","brave"
 if provider=="tavily"{service,account="GamaSearch.Tavily","tavily"}
 ctx,cancel:=context.WithTimeout(ctx,20*time.Second);defer cancel()
 // stdout is consumed locally; never logged, returned or passed to a shell.
 out,err:=exec.CommandContext(ctx,"/usr/bin/security","find-generic-password","-s",service,"-a",account,"-w").Output()
 if err!=nil{return "",fmt.Errorf("Não foi possível acessar a chave de %s no Keychain",provider)}
 key:=strings.TrimSpace(string(out));if key==""||len(key)>2048||strings.ContainsAny(key,"\r\n"){return "",fmt.Errorf("Chave inválida")}
 return key,nil
}
func gamaSearch(ctx context.Context,provider,question string)([]gamaSource,error){
 key,err:=gamaKey(ctx,provider);if err!=nil{return nil,err}
 ctx,cancel:=context.WithTimeout(ctx,15*time.Second);defer cancel()
 client:=&http.Client{Timeout:15*time.Second,Transport:&http.Transport{},CheckRedirect:func(*http.Request,[]*http.Request)error{return http.ErrUseLastResponse}}
 var req *http.Request
 if provider=="brave"{
  q:=url.Values{"q":{question},"count":{"5"},"country":{"BR"},"search_lang":{"pt-br"},"ui_lang":{"pt-BR"}}
  req,err=http.NewRequestWithContext(ctx,"GET","https://api.search.brave.com/res/v1/web/search?"+q.Encode(),nil)
  if err==nil{req.Header.Set("X-Subscription-Token",key)}
 }else if provider=="tavily"{
  body,_:=json.Marshal(map[string]any{"query":question,"search_depth":"basic","max_results":5,"include_answer":false,"include_raw_content":false,"auto_parameters":false})
  req,err=http.NewRequestWithContext(ctx,"POST","https://api.tavily.com/search",strings.NewReader(string(body)))
  if err==nil{req.Header.Set("Authorization","Bearer "+key);req.Header.Set("Content-Type","application/json")}
 }else{return nil,fmt.Errorf("invalid provider")}
 if err!=nil{return nil,fmt.Errorf("Não foi possível construir pesquisa")}
 req.Header.Set("Accept","application/json")
 res,err:=client.Do(req);if err!=nil{return nil,fmt.Errorf("Falha de conexão com %s",provider)};defer res.Body.Close()
 if res.StatusCode!=http.StatusOK{return nil,fmt.Errorf("Pesquisa %s: HTTP %d",provider,res.StatusCode)}
 data,err:=io.ReadAll(io.LimitReader(res.Body,1000001));if err!=nil||len(data)>1000000{return nil,fmt.Errorf("Resposta de pesquisa acima do limite ou inválida")}
