func gamaShort(s string,n int)string{
 s=strings.Join(strings.Fields(s)," ");r:=[]rune(s);if len(r)>n{return string(r[:n])+"…"};return s
}
func gamaParseSearch(provider string,data []byte)([]gamaSource,error){
