 var raw struct {Results []item `json:"results"`;Web struct{Results []item `json:"results"`} `json:"web"`}
 if err:=json.Unmarshal(data,&raw);err!=nil{return nil,fmt.Errorf("Resposta de pesquisa inválida")}
 items:=raw.Results;if provider=="brave"{items=raw.Web.Results}
 seen:=map[string]bool{};out:=make([]gamaSource,0,3)
 for _,x:=range items{
  u,err:=url.Parse(x.URL);if err!=nil||u.Scheme!="https"||u.Hostname()==""||u.User!=nil||len(x.URL)>1024||strings.ContainsAny(x.URL,"<>\r\n"){continue}
  if strings.HasPrefix(strings.ToLower(u.Hostname()),"localhost")||strings.HasSuffix(strings.ToLower(u.Hostname()),".local"){continue}
  if provider=="tavily" && strings.EqualFold(u.Hostname(),"tavily.com")&&strings.HasPrefix(u.Path,"/knowledge/company/"){continue}
  v:=*u;v.Fragment="";q:=v.Query();for k:=range q{if strings.HasPrefix(strings.ToLower(k),"utm_")||k=="gclid"||k=="fbclid"||(strings.EqualFold(v.Hostname(),"support.google.com")&&k=="hl"){q.Del(k)}};v.RawQuery=q.Encode()
