 var b strings.Builder
 fmt.Fprintf(&b,"\n\n**Fontes retornadas por %s (excertos de pesquisa; páginas não abertas)**\n",provider)
 for _,s:=range sources{fmt.Fprintf(&b,"\n- %s — %s: <%s>",s.ID,strings.NewReplacer("[","(","]",")","<","",">","").Replace(s.Title),s.URL)}
